:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0f0;
  --red: #ff4d4d;
  --amber: #ffcc00;
  --green: #4dff4d;
  --btn-start: #4dff4d;
  --btn-stop: #ff4d4d;
  --btn-text: #1e1e2f;
  --focus: #ffffff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.light {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  background: #111;
  padding: 16px;
  border-radius: 12px;
  margin-bottom: 24px;
  border: 4px solid #444;
}

.lamp {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: #333;
  transition: background 0.2s, box-shadow 0.2s;
  image-rendering: pixelated;
  box-shadow: inset 0 0 8px rgba(0,0,0,0.6);
}

.lamp.red.active {
  background: var(--red);
  box-shadow: 0 0 20px var(--red), inset 0 0 8px rgba(255,255,255,0.3);
}

.lamp.amber.active {
  background: var(--amber);
  box-shadow: 0 0 20px var(--amber), inset 0 0 8px rgba(255,255,255,0.3);
}

.lamp.green.active {
  background: var(--green);
  box-shadow: 0 0 20px var(--green), inset 0 0 8px rgba(255,255,255,0.3);
}

.status {
  font-size: 1.25rem;
  margin-bottom: 24px;
  min-height: 1.5em;
  font-weight: 500;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-weight: 600;
  transition: transform 0.1s, filter 0.2s, box-shadow 0.2s;
  min-width: 100px;
}

.btn.start {
  background: var(--btn-start);
  color: var(--btn-text);
}

.btn.stop {
  background: var(--btn-stop);
  color: var(--btn-text);
}

.btn:hover:not(:disabled) {
  filter: brightness(1.2);
}

.btn:active:not(:disabled) {
  transform: scale(0.96);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .lamp {
    width: 64px;
    height: 64px;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.95rem;
    min-width: 80px;
  }
}

const redLamp = document.getElementById('redLamp');
const amberLamp = document.getElementById('amberLamp');
const greenLamp = document.getElementById('greenLamp');
const statusLabel = document.getElementById('statusLabel');
const startBtn = document.getElementById('startBtn');
const stopBtn = document.getElementById('stopBtn');

const DURATIONS = { red: 3000, green: 3000, amber: 1000 };
const SEQUENCE = ['red', 'green', 'amber'];

let currentIndex = 0;
let timer = null;
let running = false;

function setLamp(color) {
  redLamp.classList.toggle('active', color === 'red');
  amberLamp.classList.toggle('active', color === 'amber');
  greenLamp.classList.toggle('active', color === 'green');
  statusLabel.textContent = 'Light: ' + color.charAt(0).toUpperCase() + color.slice(1);
}

function clearLamps() {
  redLamp.classList.remove('active');
  amberLamp.classList.remove('active');
  greenLamp.classList.remove('active');
  statusLabel.textContent = 'Light: Off';
}

function cycle() {
  const color = SEQUENCE[currentIndex];
  setLamp(color);
  timer = setTimeout(() => {
    currentIndex = (currentIndex + 1) % SEQUENCE.length;
    cycle();
  }, DURATIONS[color]);
}

function start() {
  if (running) return;
  running = true;
  startBtn.disabled = true;
  stopBtn.disabled = false;
  currentIndex = 0;
  cycle();
}

function stop() {
  if (!running) return;
  running = false;
  clearTimeout(timer);
  timer = null;
  clearLamps();
  startBtn.disabled = false;
  stopBtn.disabled = true;
}

startBtn.addEventListener('click', start);
stopBtn.addEventListener('click', stop);

// Clean up on page unload
window.addEventListener('beforeunload', () => {
  if (timer) clearTimeout(timer);
});
